userscript.function:

$share.childScreen = {};
$share.config = {
    module: {
        WORK_TYPE: "C", // T: template, C:contract
        CONT_TYPE: (Sepoa.request.alias || "B"), //B: Business, E: Employee
        CONT_MODULE: "EDITOR"
    },
    document: {
        CONT_TYPE: (Sepoa.request.alias || "B"), //B: Business, E: Employee
    },
    editor:{
        header:[]
    }
}

if(Sepoa.request.CONT_NO){
    $share.config.document.CONT_NO = Sepoa.request.CONT_NO
    $share.config.document.CONT_GL_SEQ =  Sepoa.request.CONT_GL_SEQ
    $share.config.document.isReady = false;
    doQuery();
}else{
    $share.config.document.isReady = true;
}

// sign method
if ($share.config.module.CONT_TYPE == "E") {
    // Employee
    $share.config.module.AVAILABLE_CONT_METHOD = sUtils.workflow.getOptions('CT1625189958748', true);
    $share.config.module.AVAILABLE_FILE_TYPE = sUtils.workflow.getOptions('CT1625200711940', true);
} else {
    // Bussiness
    $share.config.module.AVAILABLE_CONT_METHOD = sUtils.workflow.getOptions('CT1625190016754', true);
    $share.config.module.AVAILABLE_FILE_TYPE = sUtils.workflow.getOptions('CT1625200717734', true);
}

// Before Module settings
$share.config.module.AVAILABLE_CONT_METHOD = ['0', 'S', 'D', 'C']
$share.config.module.AVAILABLE_FILE_TYPE = ['C', 'E']


$share.config.editor.flowview = {
    options: [{
            view: 'step'
        },
        [
            {
                id: 'UPLOAD',
                label: Sepoa.cache.text.get('CT_002.FILE')
            },
            {
                id: 'MODULE',
                label: Sepoa.cache.text.get('CT_002.EDIT')
            },
            {
                id: 'END',
                label: Sepoa.cache.text.get('CT_002.SAVE')
            }
        ]
    ]
};

flowViewObj = $share.config.editor.flowview.origin = $sObject.flowViewObj = Object.create(SepoaFlowView.prototype);
SepoaFlowView.apply(flowViewObj, [flowControllerBox].concat($share.config.editor.flowview.options));
flowViewObj.attachEvent('onBeforeActive', onBeforeActive);
flowViewObj.attachEvent('onActive', onActive);


if(btn == "prev"){
    return true;
}else if (id == 'MODULE' || id == 'END') {
    var beforeInfo = $share.childScreen[before.id];
    if (beforeInfo && beforeInfo.events && beforeInfo.events.onBeforeNext) {
        var flag = beforeInfo.events.onBeforeNext(id);
        if(flag){
            doDocumentUpdate(id);
        }
    }
}        
return false;


var config = {
    url:window.CONTEXT_NAME+'/SepoaActionController.sux',
    on:{
        callback:function(res){
            if(res.status == "1"){
                $share.config.document = $.extend(true, $share.config.document, res.result[0]);
                for(var i in $share.childScreen){
                    var screenInfo = $share.childScreen[i];
                    if (screenInfo.events && screenInfo.events.onRegistration) {
                        screenInfo.events.onRegistration($share.config);
                    }
                }
                $share.config.document.isReady = true;
            }else{
                Alert(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0002'));
            }
        }
    }
}

var params = {
    module:"contract",
    action: "doDocumentDetail",
    CONNECTION: "CONNECTION",
    CONT_TYPE: $share.config.module.CONT_TYPE,
    CONT_NO: $share.config.document.CONT_NO,
    CONT_GL_SEQ: $share.config.document.CONT_GL_SEQ
}

sUtils.multipart.send(config, params);


 var config = {
    url:window.CONTEXT_NAME+'/SepoaActionController.sux',
    on:{
        callback:function(res, config, params){
            if(res.flag){
                if(params.NEXT_STEP != "END"){
                    flowViewObj.setActive(params.NEXT_STEP, true);
                }else{

                }
            }
        }
    },
    contentType:"json"
}
var params = {
    module:"contract",
    action: "doDocumentUpdate",
    CONT_NO: $share.config.document.CONT_NO,
    CONT_GL_SEQ:  $share.config.document.CONT_GL_SEQ,
    CONT_TYPE: $share.config.document.CONT_TYPE,
    NEXT_STEP: nextStep
}

switch(nextStep){
case "MODULE":
    params.DOC_INFO_DATA=$share.config.document.DOC_INFO_DATA;
    break;
case "END":
    params.DOC_INFO_DATA=$share.config.document.DOC_INFO_DATA;
    params.DOC_ITEM=$share.config.document.DOC_ITEM;
    break;
case "APPROVAL":
    //미구현
    break;
}

sUtils.multipart.send(config, params);


var config = {
    url:window.CONTEXT_NAME+'/SepoaActionController.sux',
    async:false
}

var params = {
    module:"contract",
    action: "doDocumentCreate",
    CONT_NO: $share.config.document.CONT_NO,
    CONT_GL_SEQ: $share.config.document.CONT_GL_SEQ,
    CONT_TYPE: $share.config.document.CONT_TYPE
}

return (sUtils.multipart.send(config, params).status == "1")
